/*
 * A072149  Coordination sequence for AlPO_4-11 structure with respect to node
 *          (X) where decagon and two hexagons meet.
 * https://oeis.org/A072149
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = -a(n-2) + a(n-3) + a(n-5) + a(n-9) + a(n-11) - a(n-12) -
 *            a(n-14) Initial values: a(0)=1, a(1)=3, a(2)=6, a(3)=8, a(4)=10,
 *            a(5)=13, a(6)=16, a(7)=19, a(8)=20, a(9)=22, a(10)=28, a(11)=31,
 *            a(12)=30, a(13)=33, a(14)=38 (All other terms are generated by
 *            the recurrence.)
 * Range:     u8 n <= 96, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *cache = NULL;
static idx_t cache_size = 0;

static const seq_t base_vals[15] = {
    1, 3, 6, 8, 10, 13, 16, 19, 20, 22, 28, 31, 30, 33, 38
};

/* Grow the cache up to index n (inclusive) and fill missing entries. */
static void ensure_cache(idx_t n)
{
    if (cache == NULL) {
        /* Initialise with the first 15 terms. */
        cache_size = 15;
        cache = (seq_t *)malloc(sizeof(seq_t) * cache_size);
        for (idx_t i = 0; i < cache_size; ++i)
            cache[i] = base_vals[i];
    }

    if (n < cache_size)
        return;

    /* Extend the cache. */
    seq_t *tmp = (seq_t *)realloc(cache, sizeof(seq_t) * (n + 1));
    if (tmp == NULL) {
        /* Allocation failed; terminate to avoid undefined behaviour. */
        abort();
    }
    cache = tmp;
    for (idx_t i = cache_size; i <= n; ++i) {
        long long v = -(long long)cache[i - 2];
        v += (long long)cache[i - 3];
        v += (long long)cache[i - 5];
        v += (long long)cache[i - 9];
        v += (long long)cache[i - 11];
        v -= (long long)cache[i - 12];
        v -= (long long)cache[i - 14];
        cache[i] = (seq_t)v;
    }
    cache_size = n + 1;
}

seq_t a(idx_t n)
{
    ensure_cache(n);
    return cache[n];
}
